$('optimize').onclick=optimizeProject;for(const [id,axis] of [['objectWidth','x'],['objectHeight','y']])$(id).onchange=()=>{const o=current(),value=Number($(id).value);if(!o||o.kind==='machine')return;const b=objectBounds(o),old=axis==='x'?b.maxX-b.minX:b.maxY-b.minY;if(value<1||value>300||!Number.isFinite(value)){properties();return}change(()=>{const ratio=value/old,uniform=$('keepAspect').checked;resizeRegion(o,uniform||axis==='x'?ratio:1,uniform||axis==='y'?ratio:1)});fitView()};
