function animate(t){if(!playing)return;const diff=Math.min(.1,(t-lastTime)/1000);lastTime=t;$('scrub').value=Math.min(1000,Number($('scrub').value)+diff*Number($('speed').value)/Math.max(1,pattern.commands.length)*1000);render();if(Number($('scrub').value)>=1000){playing=false;$('play').textContent='▶';return}requestAnimationFrame(animate)}$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'Ⅱ':'▶';if(playing){if(Number($('scrub').value)>=1000)$('scrub').value=0;lastTime=performance.now();requestAnimationFrame(animate)}};$('scrub').oninput=()=>{playing=false;$('play').textContent='▶';render()};
