async function importFile(file){if(!file)return;const projectId=doc.id,checkProject=()=>{if(doc.id!==projectId)throw Error('O projeto mudou durante a leitura. Importe o arquivo novamente no projeto desejado.')};try{if(file.size>15*1024*1024)throw Error('Use um arquivo de até 15 MB.');$('status').textContent='Lendo arquivo…';const ext=file.name.split('.').pop().toLowerCase();if(['pes','pec','dst'].includes(ext)){const bytes=new Uint8Array(await file.arrayBuffer());checkProject();const result=ext==='dst'?readDST(bytes):readPES(bytes);change(()=>{const o={id:uid(),name:file.name,kind:'machine',commands:result.commands,colors:result.colors,color:result.colors[0],x:0,y:0,notice:result.notice,sourceBytes:bytes64(bytes),sourceFormat:ext,dirty:false};doc.objects.push(o);selected=o.id});toast('Matriz aberta preservando seus pontos. Confira os alertas.')}else if(ext==='json'){const d=JSON.parse(await file.text());checkProject();if(d.schema!=='bordai-atelier-1'||!Array.isArray(d.objects)||d.objects.length>200)throw Error('Use um projeto BordAI Atelier desta versão.');if(JSON.stringify(d).length>20000000)throw Error('Projeto muito grande.');compile(d);checkpoint();doc=d;selected=d.objects[0]?.id;update();toast('Projeto editável restaurado.')}else{$('status').textContent='Extraindo contornos…';await new Promise(r=>setTimeout(r,30));const objects=await importArtwork(file,{width:Math.max(10,Math.min(250,Number($('imageWidth').value)||90)),mode:$('imageMode').value,maxColors:Math.max(1,Math.min(10,Number($('maxColors').value))),removeWhite:$('removeWhite').checked});checkProject();const prepared=objects[0]?.preparation;const paths=objects.reduce((s,o)=>s+o.paths.reduce((n,p)=>n+p.points.length,0),0);if(paths>30000)throw Error('Esta configuração excedeu a capacidade de edição. A arte foi preservada; reduza as cores ou use a preparação Arte delicada.');change(()=>{objects.forEach(o=>{o.id=uid();applyFabric(o,doc.fabricProfile||'custom');doc.objects.push(o)});selected=objects[0]?.id});toast(`${prepared?.adaptive?'Preparação delicada ativada automaticamente. ':''}${objects.filter(o=>o.kind==='satin').length} regiões em satin; ${objects.filter(o=>o.kind==='fill').length} preenchimentos.${objects.some(o=>o.groupedRegions)?' '+objects.reduce((n,o)=>n+(o.groupedRegions||0),0)+' detalhes agrupados por cor, sem descartar contornos.':''}${objects.some(o=>o.reference)?' '+objects.filter(o=>o.reference).length+' microdetalhes abaixo de 0,3 mm mantidos apenas como referência, sem pontos.':''}${prepared?.mergedFragments?' '+prepared.mergedFragments+' fragmentos de textura suavizados; revise a comparação com a arte.':''} Confira os alertas.`)}pathIndex=0;tab('objects');fitView();await optimizeProject()}catch(e){toast('Não foi possível importar: '+e.message);$('status').textContent='Importação interrompida'}finally{$('file').value=''}}
