function download(data,type,ext){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=(doc.name.replace(/[^\p{L}\p{N}_ -]/gu,'').trim()||'bordado')+'.'+ext;a.hidden=true;(document.querySelector('dialog[open]')||document.body).append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
