function preview(){const b=pattern.bounds,c=document.createElement('canvas');if(!Number.isFinite(b.minX))return c;const width=b.maxX-b.minX+4,height=b.maxY-b.minY+4,s=Math.min(1600/width,1200/height);c.width=Math.ceil(width*s);c.height=Math.ceil(height*s);const context=c.getContext('2d'),old=scale;scale=s;paintStitches(context,pattern.commands,p=>({x:(p.x-b.minX+2)*s,y:(p.y-b.minY+2)*s}));scale=old;return c}$('previewPNG').onclick=()=>{if(!pattern.metrics.stitches){toast('Adicione um objeto primeiro.');return}preview().toBlob(b=>download(b,'image/png','png'))};
$('productionSheet').onclick=()=>{if(!pattern.metrics.stitches){toast('Adicione um objeto primeiro.');return}const w=window.open('','_blank');if(!w){toast('Permita a abertura da ficha no navegador.');return}const d=w.document;d.title='Ficha de produção';const main=d.createElement('main');main.style.cssText='font:14px system-ui;max-width:800px;margin:40px auto;color:#263047';const h=d.createElement('h1');h.textContent=doc.name;const p=d.createElement('p');p.textContent=`BordAI Atelier · ${fmt(pattern.metrics.stitches)} pontos · ${pattern.blocks.length} blocos · ${pattern.metrics.trims} cortes · ${pattern.metrics.jumps} saltos · ${fmt(pattern.metrics.travel)} mm de deslocamento`;const img=d.createElement('img');img.src=preview().toDataURL();img.style.cssText='max-width:100%;max-height:400px;object-fit:contain';main.append(h,p,img);const table=d.createElement('div');pattern.blocks.forEach((b,i)=>{const row=d.createElement('p');row.textContent=`${i+1}. ${b.color} — ${b.name}`;row.style.borderLeft=`15px solid ${b.color}`;row.style.paddingLeft='10px';table.append(row)});main.append(table);for(const i of pattern.issues){const p=d.createElement('p');p.textContent='• '+i.message;main.append(p)}const note=d.createElement('p');note.textContent='Validar tecido, entretela, agulha, linha e tensão em uma amostra antes da produção.';const button=d.createElement('button');button.textContent='Imprimir / salvar PDF';button.onclick=()=>w.print();main.append(note,button);d.body.append(main)};
