async function proofPhoto(file){if(!file)return null;if(file.size>8*1024*1024)throw Error('Use uma foto de até 8 MB.');if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Use foto PNG, JPG ou WebP.');const url=URL.createObjectURL(file);try{const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Foto inválida.'));img.src=url});const c=document.createElement('canvas'),r=Math.min(1,600/Math.max(image.width,image.height));c.width=Math.max(1,Math.round(image.width*r));c.height=Math.max(1,Math.round(image.height*r));c.getContext('2d').drawImage(image,0,0,c.width,c.height);return c.toDataURL('image/jpeg',.78)}finally{URL.revokeObjectURL(url)}}
